// The offline shell. An app built on sutra is a folder of static files; this
// writes the service worker that keeps those files on the phone so the app opens
// with no network. Voice clips are kept the first time each one is heard.
/** Which files of an app folder belong in the offline cache. */
export const cacheable = (files, audioExts = ['mp3']) => files
    .map((f) => f.split('\\').join('/'))
    .filter((f) => f !== 'sw.js' && !f.endsWith('.md') && !f.endsWith('.DS_Store') && !audioExts.some((x) => f.startsWith('audio/') && f.endsWith('.' + x)))
    .sort();
/** The source text of sw.js. */
export const serviceWorker = (o) => {
    const exts = o.audioExts ?? ['mp3'];
    return `// Generated by sutra (sutra-sw). Do not edit by hand.
const VERSION = ${JSON.stringify(o.version)};
const PREFIX = ${JSON.stringify(o.prefix)};
const CORE = PREFIX + '-core-' + VERSION, AUDIO = PREFIX + '-audio-v1';
const ASSETS = ${JSON.stringify(['./', ...o.assets])};
const AUDIO_PATH = ${JSON.stringify(o.audioPath ?? '/audio/')}, AUDIO_EXTS = ${JSON.stringify(exts.map((x) => '.' + x))};

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CORE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX + '-core-') && k !== CORE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  const req = e.request; if (req.method !== 'GET') return;
  const url = new URL(req.url); if (url.origin !== location.origin) return;
  // Voice clips: keep each one the first time it is heard.
  if (url.pathname.includes(AUDIO_PATH) && AUDIO_EXTS.some((x) => url.pathname.endsWith(x))) {
    e.respondWith(caches.open(AUDIO).then((c) => c.match(req).then((hit) => hit || fetch(req).then((res) => { if (res.ok) c.put(req, res.clone()); return res; }))));
    return;
  }
  // Everything else: answer from the cache, fall back to the network.
  e.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).catch(() => caches.match('./'))));
});
`;
};
